/// <summary>双弧 Double Arc: Two arcs grow outward from the centre, then shrink back.</summary>
public sealed class DoubleArcEffect : EffectGenerator, ILoopable
{
    public const string EffectId = "DoubleArc";

    public DoubleArcEffect()
        : base(EffectId, new EffectParamSchema("Double Arc", "双弧", 1, 7, true, false, EffectMath.Trio, false))
